import 'package:mockito/annotations.dart';
import 'package:mockito/mockito.dart';

@GenerateNiceMocks([MockSpec<Cat>()])
import 'cat_test.mocks.dart';

class Cat {
  String sound() => "Meow";
}

void main() {
  var cat = MockCat();
  when(cat.sound()).thenReturn("Purr");
  expect(cat.sound(), "Purr");
}
